import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { callRule, type Rule, type Tree } from '@angular-devkit/schematics';
import { SchematicTestRunner, UnitTestTree } from '@angular-devkit/schematics/testing';
import { beforeEach, describe, expect, it } from 'vitest';
import { ngAdd } from './index';
import type { Schema } from './schema';

// A real Angular workspace and application are generated by Angular's own schematics into a virtual tree, so the
// rule is tested against the files `ng new` writes, not against hand-made imitations of them.
const here = fileURLToPath(new URL('.', import.meta.url));
const collection = join(here, '..', 'collection.json');

let runner: SchematicTestRunner;
let logs: { level: string; message: string }[];

beforeEach(() => {
  runner = new SchematicTestRunner('@bugsee/angular', collection);
  logs = [];
  runner.logger.subscribe((entry) => logs.push({ level: entry.level, message: entry.message }));
});

const logged = (level?: string) =>
  logs
    .filter((l) => level === undefined || l.level === level)
    .map((l) => l.message)
    .join('\n');

// biome-ignore lint/suspicious/noExplicitAny: angular.json is edited ad hoc throughout these tests
type Loose = Record<string, any>;

const NG = '@schematics/angular';

async function workspace(
  apps: { name: string; standalone?: boolean; ssr?: boolean }[] = [{ name: 'demo' }],
): Promise<UnitTestTree> {
  let tree = await runner.runExternalSchematic(NG, 'workspace', {
    name: 'ws',
    version: '22.0.0',
    newProjectRoot: 'projects',
  });
  for (const app of apps) {
    tree = await runner.runExternalSchematic(
      NG,
      'application',
      {
        name: app.name,
        projectRoot: apps.length === 1 ? '' : `projects/${app.name}`,
        standalone: app.standalone ?? true,
        routing: false,
        style: 'css',
        skipTests: true,
        ssr: app.ssr ?? false,
      },
      tree,
    );
  }
  tree.delete('/.gitignore');
  if (!tree.exists('/package.json')) {
    tree.create(
      '/package.json',
      JSON.stringify({ name: 'ws', version: '1.2.3', scripts: { ng: 'ng' } }, null, 2),
    );
  }
  return tree;
}

/** Run a rule against `tree` and resolve to the resulting tree (callRule hands back an Observable). */
const run = (tree: UnitTestTree, options: Schema = {}, rule: Rule = ngAdd(options)) =>
  new Promise<UnitTestTree>((resolve, reject) => {
    let result: Tree | undefined;
    // The runner's own context has a logger nobody can read; this one writes to `runner.logger` (see `logs`).
    const context = {
      ...runner.engine.createContext({ description: { name: 'ng-add' } } as never),
      logger: runner.logger,
    };
    callRule(rule, tree, context).subscribe({
      next: (next) => {
        result = next;
      },
      error: reject,
      complete: () => resolve(new UnitTestTree(result as Tree)),
    });
  });

const json = (tree: UnitTestTree, path: string) => JSON.parse(tree.readContent(path));
const snapshot = (tree: UnitTestTree) =>
  Object.fromEntries(tree.files.map((file) => [file, tree.readContent(file)]));

const prodOf = (tree: UnitTestTree, project = 'demo') =>
  json(tree, '/angular.json').projects[project].architect.build.configurations.production;

describe('ng add @bugsee/angular — a standalone application', () => {
  it('turns on hidden script source maps in the production configuration', async () => {
    const tree = await run(await workspace(), { appToken: 'TOKEN' });
    expect(prodOf(tree).sourceMap).toEqual({ scripts: true, styles: false, hidden: true });
  });

  it('launches the SDK in main.ts, after the imports and before the bootstrap', async () => {
    const tree = await run(await workspace(), { appToken: 'TOKEN' });
    const main = tree.readContent('/src/main.ts');
    expect(main).toContain(`import { launch } from '@bugsee/angular';`);
    expect(main).toContain(`launch('TOKEN');`);
    expect(main.indexOf(`launch('TOKEN')`)).toBeLessThan(main.indexOf('bootstrapApplication('));
    expect(main.indexOf(`launch('TOKEN')`)).toBeGreaterThan(main.lastIndexOf('import '));
  });

  it('registers BugseeErrorHandler as the ErrorHandler in the application config', async () => {
    const tree = await run(await workspace(), { appToken: 'TOKEN' });
    const config = tree.readContent('/src/app/app.config.ts');
    expect(config).toContain('BugseeErrorHandler');
    expect(config).toMatch(/provide:\s*ErrorHandler,\s*useClass:\s*BugseeErrorHandler\b/);
    expect(config).toContain(`from '@bugsee/angular'`);
    expect(config).toMatch(/import \{[^}]*ErrorHandler[^}]*\} from '@angular\/core'/);
  });

  it('adds the build:bugsee script', async () => {
    const tree = await run(await workspace(), { appToken: 'TOKEN' });
    expect(json(tree, '/package.json').scripts['build:bugsee']).toBe(
      'ng build --configuration production && bugsee-angular-upload --configuration production',
    );
    expect(json(tree, '/package.json').scripts.ng).toBe('ng');
  });

  it('keeps the token for the build in .env.bugsee-build-plugin, out of git', async () => {
    const tree = await workspace();
    tree.create('/.gitignore', 'node_modules\n');
    await run(tree, { appToken: 'TOKEN' });
    expect(tree.readContent('/.env.bugsee-build-plugin')).toBe('BUGSEE_APP_TOKEN=TOKEN\n');
    expect(tree.readContent('/.gitignore')).toBe('node_modules\n.env.bugsee-build-plugin\n');
  });

  it('creates a .gitignore when there is none, and does not duplicate the entry', async () => {
    const tree = await run(await workspace(), { appToken: 'TOKEN' });
    expect(tree.readContent('/.gitignore')).toBe('.env.bugsee-build-plugin\n');
    const again = await run(tree, { appToken: 'TOKEN' });
    expect(again.readContent('/.gitignore')).toBe('.env.bugsee-build-plugin\n');
  });

  it('adds a missing newline before the .gitignore entry', async () => {
    const tree = await workspace();
    tree.create('/.gitignore', 'dist');
    await run(tree, { appToken: 'TOKEN' });
    expect(tree.readContent('/.gitignore')).toBe('dist\n.env.bugsee-build-plugin\n');
  });

  it('is idempotent: a second run changes nothing', async () => {
    const first = await run(await workspace(), { appToken: 'TOKEN' });
    const before = snapshot(first);
    const second = await run(first, { appToken: 'TOKEN' });
    expect(snapshot(second)).toEqual(before);
  });

  it('does not touch what is already set up, even with another token', async () => {
    const first = await run(await workspace(), { appToken: 'TOKEN' });
    const before = snapshot(first);
    const second = await run(first, { appToken: 'OTHER' });
    expect(snapshot(second)).toEqual(before);
    expect(second.readContent('/src/main.ts')).toContain(`launch('TOKEN')`);
  });
});

describe('ng add @bugsee/angular — an NgModule application', () => {
  it('registers the ErrorHandler in AppModule and launches in main.ts', async () => {
    const tree = await run(await workspace([{ name: 'demo', standalone: false }]), {
      appToken: 'T',
    });
    const modulePath = tree.files.find((f) => /app[.-]module\.ts$/.test(f)) as string;
    const module = tree.readContent(modulePath);
    expect(module).toContain('BugseeErrorHandler');
    expect(module).toMatch(/provide:\s*ErrorHandler,\s*useClass:\s*BugseeErrorHandler\b/);
    expect(tree.readContent('/src/main.ts')).toContain(`launch('T');`);
    expect(tree.readContent('/src/main.ts')).toContain('bootstrapModule');
  });

  it('is idempotent', async () => {
    const first = await run(await workspace([{ name: 'demo', standalone: false }]), {
      appToken: 'T',
    });
    const second = await run(first, { appToken: 'T' });
    expect(snapshot(second)).toEqual(snapshot(first));
  });
});

describe('ng add @bugsee/angular — without a token', () => {
  it('writes a placeholder, creates no env file, and says what to do', async () => {
    const tree = await run(await workspace(), {});
    expect(tree.readContent('/src/main.ts')).toContain(`launch('YOUR_APP_TOKEN');`);
    expect(tree.exists('/.env.bugsee-build-plugin')).toBe(false);
    expect(logged('warn')).toMatch(/YOUR_APP_TOKEN/);
    expect(logged('warn')).toMatch(/BUGSEE_APP_TOKEN/);
  });

  it('treats a blank token as none', async () => {
    const tree = await run(await workspace(), { appToken: '   ' });
    expect(tree.readContent('/src/main.ts')).toContain(`launch('YOUR_APP_TOKEN');`);
  });

  it('rejects a token with a line break, which would inject a line into the env file', async () => {
    const tree = await workspace();
    await expect(run(tree, { appToken: 'abc\nBUGSEE_ENDPOINT=https://evil' })).rejects.toThrow(
      /line break/,
    );
    await expect(run(tree, { appToken: 'abc\rdef' })).rejects.toThrow(/line break/);
    expect(tree.exists('/.env.bugsee-build-plugin')).toBe(false);
  });

  it('escapes a quote in the token so the launch call stays valid', async () => {
    const tree = await run(await workspace(), { appToken: `a'b\\c` });
    expect(tree.readContent('/src/main.ts')).toContain(`launch('a\\'b\\\\c');`);
  });
});

describe('ng add @bugsee/angular — the .env file', () => {
  it('appends the token to an env file that has other settings, and leaves one that has a token alone', async () => {
    const tree = await workspace();
    tree.create('/.env.bugsee-build-plugin', 'BUGSEE_ENDPOINT=https://x');
    await run(tree, { appToken: 'T' });
    expect(tree.readContent('/.env.bugsee-build-plugin')).toBe(
      'BUGSEE_ENDPOINT=https://x\nBUGSEE_APP_TOKEN=T\n',
    );
    const kept = await workspace();
    kept.create('/.env.bugsee-build-plugin', 'BUGSEE_APP_TOKEN=mine\n');
    await run(kept, { appToken: 'T' });
    expect(kept.readContent('/.env.bugsee-build-plugin')).toBe('BUGSEE_APP_TOKEN=mine\n');
  });
});

describe('ng add @bugsee/angular — source maps in angular.json', () => {
  const setBuild = (tree: UnitTestTree, edit: (build: Loose) => void) => {
    const ws = json(tree, '/angular.json');
    edit(ws.projects.demo.architect.build);
    tree.overwrite('/angular.json', JSON.stringify(ws, null, 2));
  };

  it('replaces a production sourceMap that is off', async () => {
    const tree = await workspace();
    setBuild(tree, (b) => {
      b.configurations.production.sourceMap = false;
    });
    await run(tree, { appToken: 'T' });
    expect(prodOf(tree).sourceMap).toEqual({ scripts: true, styles: false, hidden: true });
  });

  it('replaces an object with scripts off, but keeps the rest of the object', async () => {
    const tree = await workspace();
    setBuild(tree, (b) => {
      b.configurations.production.sourceMap = { scripts: false, styles: true, vendor: true };
    });
    await run(tree, { appToken: 'T' });
    expect(prodOf(tree).sourceMap).toEqual({
      scripts: true,
      styles: true,
      vendor: true,
      hidden: true,
    });
  });

  it('leaves a production sourceMap that already includes scripts exactly as the user wrote it', async () => {
    for (const value of [true, { scripts: true, hidden: false }, { styles: false }]) {
      const tree = await workspace();
      setBuild(tree, (b) => {
        b.configurations.production.sourceMap = value;
      });
      await run(tree, { appToken: 'T' });
      expect(prodOf(tree).sourceMap).toEqual(value);
    }
  });

  it('leaves it alone when the build options already turn maps on for every configuration', async () => {
    const tree = await workspace();
    setBuild(tree, (b) => {
      b.options.sourceMap = true;
    });
    await run(tree, { appToken: 'T' });
    expect(prodOf(tree).sourceMap).toBeUndefined();
  });

  it('creates the production configuration when the project has none', async () => {
    const tree = await workspace();
    setBuild(tree, (b) => {
      delete b.configurations;
      delete b.defaultConfiguration;
    });
    await run(tree, { appToken: 'T' });
    expect(prodOf(tree).sourceMap).toEqual({ scripts: true, styles: false, hidden: true });
  });

  it('adds the production configuration next to a development-only set', async () => {
    const tree = await workspace();
    setBuild(tree, (b) => {
      b.configurations = { development: { optimization: false } };
    });
    await run(tree, { appToken: 'T' });
    const configs = json(tree, '/angular.json').projects.demo.architect.build.configurations;
    expect(configs.development).toEqual({ optimization: false });
    expect(configs.production.sourceMap).toEqual({ scripts: true, styles: false, hidden: true });
  });
});

describe('ng add @bugsee/angular — choosing the project', () => {
  it('uses the only application, ignoring libraries', async () => {
    const tree = await workspace();
    const ws = json(tree, '/angular.json');
    ws.projects.lib = { projectType: 'library', root: 'projects/lib', architect: {} };
    tree.overwrite('/angular.json', JSON.stringify(ws));
    const out = await run(tree, { appToken: 'T' });
    expect(prodOf(out).sourceMap.scripts).toBe(true);
  });

  it('asks for --project when there are several applications', async () => {
    const tree = await workspace([{ name: 'one' }, { name: 'two' }]);
    await expect(run(tree, { appToken: 'T' })).rejects.toThrow(/--project.*one, two/);
  });

  it('sets up the named application and puts its name in the script', async () => {
    const tree = await run(await workspace([{ name: 'one' }, { name: 'two' }]), {
      project: 'two',
      appToken: 'T',
    });
    expect(prodOf(tree, 'two').sourceMap.scripts).toBe(true);
    expect(prodOf(tree, 'one').sourceMap).toBeUndefined();
    expect(tree.readContent('/projects/two/src/main.ts')).toContain(`launch('T')`);
    expect(tree.readContent('/projects/one/src/main.ts')).not.toContain('launch');
    expect(json(tree, '/package.json').scripts['build:bugsee']).toBe(
      'ng build two --configuration production && bugsee-angular-upload --project two --configuration production',
    );
  });

  it('rejects a project that does not exist', async () => {
    await expect(run(await workspace(), { project: 'nope' })).rejects.toThrow(/no project "nope"/);
  });

  it('rejects a workspace with no application', async () => {
    const tree = await workspace();
    tree.overwrite('/angular.json', JSON.stringify({ version: 1, projects: {} }));
    await expect(run(tree, {})).rejects.toThrow(/no application project/);
  });

  it('rejects a project that has no build target', async () => {
    const tree = await workspace();
    const ws = json(tree, '/angular.json');
    delete ws.projects.demo.architect.build;
    tree.overwrite('/angular.json', JSON.stringify(ws));
    await expect(run(tree, {})).rejects.toThrow(/no "build" target/);
  });
});

describe('ng add @bugsee/angular — when it cannot tell how the app starts', () => {
  it('changes no source, says what to add by hand, and still sets up the build', async () => {
    const tree = await workspace();
    tree.overwrite('/src/main.ts', `import('./boot').then((m) => m.start());\n`);
    const before = tree.readContent('/src/app/app.config.ts');
    await run(tree, { appToken: 'T' });
    expect(tree.readContent('/src/main.ts')).toBe(`import('./boot').then((m) => m.start());\n`);
    expect(tree.readContent('/src/app/app.config.ts')).toBe(before);
    expect(logged('warn')).toMatch(/could not find where the app bootstraps/);
    expect(logged('warn')).toMatch(/launch\('T'\)/);
    expect(logged('warn')).toMatch(/BugseeErrorHandler/);
    expect(prodOf(tree).sourceMap.scripts).toBe(true);
    expect(json(tree, '/package.json').scripts['build:bugsee']).toBeDefined();
  });

  it('says so when the entry file is missing', async () => {
    const tree = await workspace();
    tree.delete('/src/main.ts');
    await run(tree, { appToken: 'T' });
    expect(logged('warn')).toMatch(/could not find where the app bootstraps/);
  });

  it('launches but explains the ErrorHandler step when the provider cannot be added', async () => {
    const tree = await workspace();
    tree.overwrite(
      '/src/main.ts',
      `import { bootstrapApplication } from '@angular/platform-browser';\nimport { App } from './app/app';\n\nbootstrapApplication(App, makeConfig());\n`,
    );
    await run(tree, { appToken: 'T' });
    expect(tree.readContent('/src/main.ts')).toContain(`launch('T');`);
    expect(logged('warn')).toMatch(/could not register BugseeErrorHandler/);
    expect(logged('warn')).toMatch(/provide: ErrorHandler, useClass: BugseeErrorHandler/);
  });

  it('puts the launch first in a main.ts that has no imports', async () => {
    const tree = await workspace();
    tree.overwrite('/src/main.ts', `platformBrowser().bootstrapModule(AppModule);\n`);
    await run(tree, { appToken: 'T' });
    expect(
      tree.readContent('/src/main.ts').startsWith(`import { launch } from '@bugsee/angular';`),
    ).toBe(true);
  });

  it('inserts after the last of several imports, including a side-effect import', async () => {
    const tree = await workspace();
    tree.overwrite(
      '/src/main.ts',
      `import { a } from 'a';\nimport {\n  b,\n  c,\n} from 'b';\nimport 'zone.js';\n\nbootstrapApplication(App, appConfig);\n`,
    );
    await run(tree, { appToken: 'T' });
    const main = tree.readContent('/src/main.ts');
    expect(main.indexOf(`from '@bugsee/angular'`)).toBeGreaterThan(
      main.indexOf(`import 'zone.js'`),
    );
    expect(main.indexOf(`launch('T')`)).toBeLessThan(main.indexOf('bootstrapApplication'));
  });

  it('does not mistake a call that merely starts with "import" for an import', async () => {
    const tree = await workspace();
    tree.overwrite(
      '/src/main.ts',
      `import { a } from 'a';\nimportScripts('worker.js');\nbootstrapApplication(App, appConfig);\n`,
    );
    await run(tree, { appToken: 'T' });
    const main = tree.readContent('/src/main.ts');
    expect(main.indexOf(`from '@bugsee/angular'`)).toBeLessThan(main.indexOf('importScripts'));
  });

  it('finds the entry file when angular.json spells it with a leading ./', async () => {
    const tree = await workspace();
    const ws = json(tree, '/angular.json');
    ws.projects.demo.architect.build.options.browser = './src/main.ts';
    tree.overwrite('/angular.json', JSON.stringify(ws, null, 2));
    await run(tree, { appToken: 'T' });
    expect(tree.readContent('/src/main.ts')).toContain(`launch('T');`);
  });
});

describe('ng add @bugsee/angular — an app already using Bugsee', () => {
  it('does not launch twice, and does not add a second handler', async () => {
    const tree = await workspace();
    tree.overwrite(
      '/src/main.ts',
      `import { launch } from '@bugsee/bugsee';\nimport { bootstrapApplication } from '@angular/platform-browser';\nlaunch('mine');\nbootstrapApplication(App, appConfig);\n`,
    );
    await run(tree, { appToken: 'T' });
    expect(tree.readContent('/src/main.ts')).not.toContain(`launch('T')`);
    expect(tree.readContent('/src/main.ts').match(/launch\(/g)).toHaveLength(1);
  });

  it('does not add a handler when the app already provides BugseeErrorHandler somewhere', async () => {
    const tree = await workspace();
    tree.create(
      '/src/app/errors.ts',
      `import { BugseeErrorHandler } from '@bugsee/angular';\nexport const X = BugseeErrorHandler;\n`,
    );
    await run(tree, { appToken: 'T' });
    expect(tree.readContent('/src/app/app.config.ts')).not.toContain('BugseeErrorHandler');
  });
});

describe('ng add @bugsee/angular — an app that already has its own ErrorHandler', () => {
  const MINE = `{ provide: ErrorHandler, useClass: MyHandler }`;

  it('standalone: does not add a second handler (the last one wins and would silence theirs), and says what to do', async () => {
    const tree = await workspace();
    const config = tree
      .readContent('/src/app/app.config.ts')
      .replace('providers: [', `providers: [\n    ${MINE},`)
      .replace(/^/, `import { ErrorHandler } from '@angular/core';\nclass MyHandler {}\n`);
    tree.overwrite('/src/app/app.config.ts', config);
    await run(tree, { appToken: 'T' });
    expect(tree.readContent('/src/app/app.config.ts')).toBe(config);
    expect(tree.readContent('/src/main.ts')).toContain(`launch('T');`);
    expect(logged('warn')).toMatch(/already provides its own ErrorHandler/);
    expect(logged('warn')).toMatch(/reportAngularError\(error\)/);
    expect(logged('warn')).toMatch(/createAngularErrorHandler\(\{ delegate/);
  });

  it('NgModule: the same', async () => {
    const tree = await workspace([{ name: 'demo', standalone: false }]);
    const modulePath = tree.files.find((f) => /app[.-]module\.ts$/.test(f)) as string;
    const module = tree
      .readContent(modulePath)
      .replace('providers: [', `providers: [\n    ${MINE},`)
      .replace(/^/, `import { ErrorHandler } from '@angular/core';\nclass MyHandler {}\n`);
    tree.overwrite(modulePath, module);
    await run(tree, { appToken: 'T' });
    expect(tree.readContent(modulePath)).toBe(module);
    expect(logged('warn')).toMatch(/already provides its own ErrorHandler/);
  });

  it('is idempotent with it', async () => {
    const tree = await workspace();
    tree.create(
      '/src/app/handler.ts',
      `export const p = { provide: ErrorHandler,\n  useClass: MyHandler };\n`,
    );
    const first = await run(tree, { appToken: 'T' });
    const before = snapshot(first);
    const second = await run(first, { appToken: 'T' });
    expect(snapshot(second)).toEqual(before);
  });

  it('does not mistake another token that starts with ErrorHandler for it', async () => {
    const tree = await workspace();
    tree.create('/src/app/x.ts', `export const p = { provide: ErrorHandlerLike, useClass: X };\n`);
    await run(tree, { appToken: 'T' });
    expect(tree.readContent('/src/app/app.config.ts')).toContain('BugseeErrorHandler');
  });

  it('ignores a test double in a spec file', async () => {
    const tree = await workspace();
    tree.create(
      '/src/app/x.spec.ts',
      `TestBed.configureTestingModule({ providers: [${MINE}] });\n`,
    );
    await run(tree, { appToken: 'T' });
    expect(tree.readContent('/src/app/app.config.ts')).toContain('BugseeErrorHandler');
  });
});

describe('ng add @bugsee/angular — the build script', () => {
  const setScripts = (tree: UnitTestTree, scripts: Record<string, string>, indent = 2) => {
    tree.overwrite('/package.json', `${JSON.stringify({ name: 'x', scripts }, null, indent)}\n`);
  };

  it('keeps a build:bugsee script the user already has, and says so', async () => {
    const tree = await workspace();
    setScripts(tree, { 'build:bugsee': 'custom' });
    await run(tree, { appToken: 'T' });
    expect(json(tree, '/package.json').scripts['build:bugsee']).toBe('custom');
    expect(logged('info')).toMatch(/build:bugsee.*already/);
  });

  it('preserves the file indentation and trailing newline', async () => {
    const tree = await workspace();
    setScripts(tree, { start: 'ng serve' }, 4);
    await run(tree, { appToken: 'T' });
    const text = tree.readContent('/package.json');
    expect(text).toContain('\n    "scripts": {');
    expect(text.endsWith('}\n')).toBe(true);
  });

  it('creates the scripts object when package.json has none', async () => {
    const tree = await workspace();
    tree.overwrite('/package.json', '{"name":"x"}');
    await run(tree, { appToken: 'T' });
    expect(json(tree, '/package.json').scripts['build:bugsee']).toBeDefined();
    expect(tree.readContent('/package.json').endsWith('\n')).toBe(false);
  });

  it('warns instead of failing when there is no package.json', async () => {
    const tree = await workspace();
    tree.delete('/package.json');
    await run(tree, { appToken: 'T' });
    expect(logged('warn')).toMatch(/no package\.json/);
  });
});

describe('ng add @bugsee/angular — what the build step cannot do, said up front', () => {
  const setBuild = (tree: UnitTestTree, edit: (build: Loose) => void) => {
    const ws = json(tree, '/angular.json');
    edit(ws.projects.demo.architect.build);
    tree.overwrite('/angular.json', JSON.stringify(ws, null, 2));
  };

  it('explains that subresourceIntegrity is handled', async () => {
    const tree = await workspace();
    setBuild(tree, (b) => {
      b.configurations.production.subresourceIntegrity = true;
    });
    await run(tree, { appToken: 'T' });
    expect(logged('info')).toMatch(/subresourceIntegrity.*re-written/);
  });

  it('explains that service worker manifests are re-computed', async () => {
    const tree = await workspace();
    setBuild(tree, (b) => {
      b.options.serviceWorker = 'ngsw-config.json';
    });
    await run(tree, { appToken: 'T' });
    expect(logged('info')).toMatch(/serviceWorker.*re-computes/);
  });

  it('says nothing about either when neither is on', async () => {
    await run(await workspace(), { appToken: 'T' });
    expect(logged()).not.toMatch(/subresourceIntegrity|serviceWorker/);
  });
});

describe('ng add @bugsee/angular — the webpack browser builder', () => {
  it('reads the entry from `main`, sets up the same way, and names the builder in the notes', async () => {
    const tree = await workspace();
    const ws = json(tree, '/angular.json');
    const build = ws.projects.demo.architect.build;
    build.builder = '@angular-devkit/build-angular:browser';
    build.options.main = build.options.browser;
    delete build.options.browser;
    tree.overwrite('/angular.json', JSON.stringify(ws, null, 2));
    await run(tree, { appToken: 'T' });
    expect(tree.readContent('/src/main.ts')).toContain(`launch('T');`);
    expect(prodOf(tree).sourceMap.scripts).toBe(true);
    expect(logged('info')).toMatch(/@angular-devkit\/build-angular:browser/);
  });
});
